package com.masaakis.kitchen.api;import com.masaakis.kitchen.application.KitchenService;import jakarta.validation.constraints.Pattern;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;@Validated@RestController@RequestMapping("/api/public/pickups")public class PickupBoardController{private final KitchenService service;public PickupBoardController(KitchenService s){service=s;}@GetMapping("/{slug}")KitchenService.PickupBoard board(@PathVariable@Pattern(regexp="[a-z0-9-]{3,80}")String slug){return service.board(slug);}}
